mapper.select:
select m.month_id, m.shop_dept_id, sd.dept_name as shop_dept_name, m.quota_year, m.quota_month,
       m.annual_repair_ratio, m.asset_total_amount, m.monthly_quota_amount,
       m.create_by, m.create_time, m.update_by, m.update_time, m.remark
from oa_fixed_asset_quota_month m
left join sys_dept sd on sd.dept_id = m.shop_dept_id
where m.shop_dept_id = #{shopDeptId}
  and m.quota_year = #{quotaYear}
  and m.quota_month = #{quotaMonth}

select coalesce(sum(monthly_quota_amount), 0)
from oa_fixed_asset_quota_month
where shop_dept_id = #{shopDeptId}
  and quota_year = #{quotaYear}
  and quota_month <= #{throughMonth}

mapper.insert:
insert into oa_fixed_asset_quota_month (
    shop_dept_id, quota_year, quota_month, annual_repair_ratio, asset_total_amount,
    monthly_quota_amount, create_by, create_time, remark
) values (
    #{shopDeptId}, #{quotaYear}, #{quotaMonth}, #{annualRepairRatio}, #{assetTotalAmount},
    #{monthlyQuotaAmount}, #{createBy}, sysdate(), #{remark}
)
